import { headers } from 'next/headers';

type PreferenceValue = string | number | boolean | null | undefined | Record<string, unknown> | Array<unknown>;

type PreferencesResponse = {
  preferences?: Record<string, PreferenceValue>;
  [key: string]: unknown;
};

function getBaseUrl(headersList: ReturnType<typeof headers>) {
  const forwardedHost = headersList.get('x-forwarded-host');
  const host = forwardedHost ?? headersList.get('host');
  const protocol = headersList.get('x-forwarded-proto') ?? 'http';

  if (host) {
    return `${protocol}://${host}`;
  }

  if (process.env.NEXT_PUBLIC_SITE_URL) {
    return process.env.NEXT_PUBLIC_SITE_URL;
  }

  if (process.env.VERCEL_URL) {
    return `https://${process.env.VERCEL_URL}`;
  }

  return 'http://localhost:3000';
}

async function getUserPreferences() {
  try {
    const headersList = headers();
    const baseUrl = getBaseUrl(headersList);
    const cookie = headersList.get('cookie');
    const authorization = headersList.get('authorization');
    const outgoingHeaders: Record<string, string> = {};

    if (cookie) {
      outgoingHeaders.cookie = cookie;
    }

    if (authorization) {
      outgoingHeaders.authorization = authorization;
    }

    const res = await fetch(`${baseUrl}/api/user/preferences`, {
      cache: 'no-store',
      headers: outgoingHeaders,
    });
    if (!res.ok) {
      return null;
    }
    return (await res.json()) as PreferencesResponse;
  } catch {
    return null;
  }
}

function formatPreferenceValue(value: PreferenceValue) {
  if (value === null || value === undefined) {
    return 'Not set';
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  return JSON.stringify(value);
}

export default async function UserDashboard() {
  const data = await getUserPreferences();
  const preferences =
    data && typeof data === 'object' && 'preferences' in data && data.preferences
      ? data.preferences
      : (data as Record<string, PreferenceValue> | null);

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Current preferences (fetched per request)</p>
      {preferences ? (
        <dl>
          {Object.entries(preferences).map(([key, value]) => (
            <div key={key}>
              <dt>{key}</dt>
              <dd>{formatPreferenceValue(value)}</dd>
            </div>
          ))}
        </dl>
      ) : (
        <p>Unable to load preferences.</p>
      )}
    </div>
  );
}
